    "originalText": "द्वितीय विश्वयुद्ध के कुछ बाद ही संयुक्त राष्ट्र (अमरीका) के दक्षिणी भाग में सिलाई द्वारा कालीन बनाने की मशीन का आविष्कार हुआ। इनसे 'गुच्छित' कालीन बनते हैं",
